# R-545 (10 Oct): the staging branch (R-161) moves applied migrations to prisma/migrations/<name>/migration.sql,
# so look there too — the staging DB run stopped at "Missing file" on 20261006130000.
migsrc() { if [ -f "$HERE/migrations/$1" ]; then echo "$HERE/migrations/$1"; elif [ -f "$HERE/../prisma/migrations/${1%.sql}/migration.sql" ]; then echo "$HERE/../prisma/migrations/${1%.sql}/migration.sql"; fi; }
# Fail before touching anything if a listed file is missing or a key repeats.
seen=" "
for m in "${MIGS[@]}"; do
  IFS='|' read -r k f _ <<< "$m"   # R-2480: no subshell per line (Git Bash forks are slow)
  [ -n "$(migsrc "$f")" ] || { echo "Missing file: migrations/$f — nothing changed. Send Claude this screen."; exit 1; }
  case "$seen" in *" $k "*) echo "Key '$k' twice in MIGS — nothing changed."; exit 1;; esac
  seen="$seen$k "
done

TMP="$(mktemp -d)"; trap 'rm -rf "$TMP"' EXIT
{
  echo 'DO $$ DECLARE r text; BEGIN'
  # R-1622: concat_ws() takes at most 100 arguments; at 134 migrations the PEEK failed and the
  # script stopped silently. array_to_string(ARRAY[...]) has no such limit.
  echo "  SELECT array_to_string(ARRAY[''::text"
  sep=","
  for m in "${MIGS[@]}"; do
    IFS='|' read -r k _ _ p <<< "$m"
    printf "   %s'%s=' || coalesce((%s)::text, 'null')\n" "$sep" "$k" "$p"
  done
  # R-2480: the "other parts" check of each migration a later one supersedes (key_rest=…). coalesce:
  # every key answers (null → 'null'), so a cut-short PEEK line is caught below, never read as "apply".
  for s in "${SUPS[@]}"; do
    IFS='|' read -r k _ r <<< "$s"; if [ -n "$r" ]; then printf "   ,'%s_rest=' || coalesce((%s)::text, 'null')\n" "$k" "$r"; fi
  done
  echo "  ]::text[], ' ') INTO r;"
  echo "  RAISE EXCEPTION 'PEEK %', r; END \$\$;"
} > "$TMP/peek-live.sql"
printf "notify pgrst, 'reload schema';\n" > "$TMP/reload.sql"

peek() { # $1 = sql file that RAISEs 'PEEK …'; prints the PEEK line (the import is MEANT to fail)
  # R-2357 (2 Nov 2026): never exit from here. Under set -euo pipefail an empty grep (no PEEK line —
  # the import failed with some OTHER error, that day "permission denied for schema storage") killed
  # the script inside $(peek …) with no message, before the caller's "Could not read" line. Now: the
  # PEEK line on stdout, or the import's own error on stderr and nothing on stdout.
  local ops line
  if ! gcloud storage cp "$1" "$B/$(basename "$1")" --project="$P" -q >/dev/null 2>&1; then
    echo "Could not upload $(basename "$1") to $B." >&2; return 0
  fi
  gcloud sql import sql "$I" "$B/$(basename "$1")" --database="$DB" --user=resellersos_migration --project="$P" --quiet >/dev/null 2>&1 || true
  ops="$(gcloud sql operations list --instance="$I" --project="$P" --limit=1 --format=json 2>&1)" || true
  line="$(printf '%s\n' "$ops" | grep -oE 'PEEK[^\\"]*' | head -1)" || true
  if [ -n "$line" ]; then echo "$line"; return 0; fi
  echo "No PEEK line from the read-only check. What the import said:" >&2
  printf '%s\n' "$ops" | grep -oE 'ERROR[^\\"]*|"message": *"[^"]*"' | head -3 >&2 || true
}
is_true() { echo "$1" | grep -qE "(^| )$2=true([^a-z0-9_]|$)"; }   # $1 = PEEK line, $2 = key (last key is glued to "CONTEXT:")

# R-2480 (5 Nov 2026): never RE-RUN a superseded migration. Re-running an older file whose function a
# newer, already-applied file redefined puts the OLD body back (R-2383 over R-2447's approval rule).
# plan "<PEEK line>" sets ST[key] for every MIGS key, newest first:
#   in         — its peek is true;
#   superseded — peek not true, a LATER migration redefining its function/view is in (or itself superseded)
#                and its other parts are in (key_rest true): NOT re-run, reported as superseded (green);
#   blocked    — a later redefiner is in but its other parts are NOT: re-running brings the old body back,
#                skipping loses a column/table — the script stops before any change;
#   apply      — anything else (e.g. a fresh DB): applied in file order, exactly as before.
# GAP = keys the PEEK line has no answer (true/false/null) for.
# ACCEPT_SUPERSEDED="key1 key2" (env): after Claude has checked them, blocked keys count as superseded —
# the way on when a later migration on purpose removed what an older peek checks (no header may be edited).
declare -A LATER=() REST=() VAL=() ST=() BY=()
for s in "${SUPS[@]}"; do IFS='|' read -r k l r <<< "$s"; LATER[$k]="$l"; REST[$k]="$r"; done
GAP=""
plan() {
  local w k v i later by
  VAL=(); ST=(); BY=(); GAP=""
  for w in $1; do
    case "$w" in [A-Za-z0-9]*=*) k="${w%%=*}"; v="${w#*=}"; v="${v%%[!a-z]*}" ;; *) continue;; esac
    case "$k" in *[!A-Za-z0-9_]*) continue;; esac
    case "$v" in true|false|null) VAL[$k]="$v";; esac
  done
  for (( i=${#MIGS[@]}-1; i>=0; i-- )); do
    k="${MIGS[$i]%%|*}"
    if [ -z "${VAL[$k]:-}" ]; then GAP="$GAP $k"; fi
    if [ "${VAL[$k]:-}" = true ]; then ST[$k]=in; continue; fi
    by=""
    for later in ${LATER[$k]:-}; do   # name a later one that is IN, else one itself superseded
      case "${ST[$later]:-}" in in) by="$later"; break;; superseded) [ -n "$by" ] || by="$later";; esac
    done
    if [ -z "$by" ]; then ST[$k]=apply
    elif [ -n "${REST[$k]:-}" ] && [ "${VAL[${k}_rest]:-}" = true ]; then ST[$k]=superseded; BY[$k]="$by"
    elif [[ " ${ACCEPT_SUPERSEDED:-} " == *" $k "* ]]; then ST[$k]=superseded; BY[$k]="$by (ACCEPT_SUPERSEDED)"
    else ST[$k]=blocked; BY[$k]="$by"
    fi
  done
  return 0
}

say "0. Who is logged in (must be your account) and which project"
gcloud config get-value account
echo "project: $P   instance: $I   migrations listed: ${#MIGS[@]}"

say "1. Backup live DB before anything changes"
gcloud sql backups create --instance="$I" --project="$P" --description="before 7 Oct 2026 deploy (${#MIGS[@]} migrations, R-348)"
gcloud sql backups list --instance="$I" --project="$P" --limit=1 --format="table(id,status,windowStartTime)"
BST="$(gcloud sql backups list --instance="$I" --project="$P" --limit=1 --format='value(status)')"
[ "$BST" = "SUCCESSFUL" ] || { echo "Latest backup is '$BST', not SUCCESSFUL — nothing changed. Send Claude this screen."; exit 1; }

say "2. What live has now (read-only)"
BEFORE="$(peek "$TMP/peek-live.sql")"
echo "$BEFORE"
[ -n "$BEFORE" ] || { echo "Could not read live — nothing changed. Send Claude a screenshot."; exit 1; }
plan "$BEFORE"
if [ -n "$GAP" ]; then echo "The read-only check did not answer for:$GAP — nothing changed. Send Claude this screen."; exit 1; fi
blocked=""
for m in "${MIGS[@]}"; do k="${m%%|*}"; if [ "${ST[$k]}" = blocked ]; then blocked="$blocked $k"; fi; done
if [ -n "$blocked" ]; then
  echo "STOPPED before any change (R-2480). These migrations are not in, but a NEWER migration that redefines the same function/view IS:"
  for k in $blocked; do echo "  $k (newer: ${BY[$k]})"; done
  echo "Re-running them would put the OLD function body back, and their other parts (columns/tables/triggers) are not all in, so skipping is not safe either."
  echo "Nothing changed. Send Claude this screen — the fix is a NEW migration that adds the missing parts (or, once Claude has checked, ACCEPT_SUPERSEDED=\"<keys>\")."
  exit 1
fi

apply() { # $1 = migration file name, $2 = db user
  local f; f="$(migsrc "$1")"
  echo "-- applying $1 as $2"
  gcloud storage cp "$f" "$B/$1" --project="$P" -q >/dev/null
  if ! gcloud sql import sql "$I" "$B/$1" --database="$DB" --user="$2" --project="$P" --quiet; then
    echo; echo "STOPPED at $1. Files after it were NOT applied. (feedback_checked + salary_payments roll back whole; the others have no begin/commit and may be partly in — all are re-runnable, but Claude checks before any retry.)"
    gcloud sql operations list --instance="$I" --project="$P" --limit=1 --format="value(error.errors[0].message)" | tr '\\' '\n' | grep -E "ERROR" | head -3
    echo "Send Claude this screen. Do not retry by hand."
    exit 1
  fi
}

say "3. Apply what is missing, in file order"
for m in "${MIGS[@]}"; do
  IFS='|' read -r k f u _ <<< "$m"
  case "${ST[$k]}" in
    in) echo "-- $k: already on live, skipped";;
    superseded) echo "-- $k: superseded by ${BY[$k]} (a newer body of its function is in) — not re-run (R-2480)";;
    *) apply "$f" "$u";;
  esac
done

say "3b. Grant what the RLS policies already allow (cloudsql/09) — re-runnable"
gcloud storage cp "$HERE/cloudsql/09-grant-what-policies-allow.sql" "$B/09-grant.sql" --project="$P" -q >/dev/null
gcloud sql import sql "$I" "$B/09-grant.sql" --database="$DB" --user=resellersos_migration --project="$P" --quiet

say "3c. service_role may run the functions RLS policies call (cloudsql/10) — re-runnable"
gcloud storage cp "$HERE/cloudsql/10-service-role-policy-functions.sql" "$B/10-grants.sql" --project="$P" -q >/dev/null
gcloud sql import sql "$I" "$B/10-grants.sql" --database="$DB" --user=resellersos_migration --project="$P" --quiet

say "4. Tell PostgREST about the new columns/functions (schema reload)"
gcloud storage cp "$TMP/reload.sql" "$B/reload.sql" --project="$P" -q >/dev/null
gcloud sql import sql "$I" "$B/reload.sql" --database="$DB" --user=resellersos_migration --project="$P" --quiet

say "5. What live has now"
AFTER="$(peek "$TMP/peek-live.sql")"
echo "$AFTER"
missing=""; superseded=""
if [ -n "$AFTER" ]; then plan "$AFTER"; else ST=(); fi
for m in "${MIGS[@]}"; do
  k="${m%%|*}"
  case "${ST[$k]:-}" in in) ;; superseded) superseded="$superseded $k";; *) missing="$missing $k";; esac
done
if [ -n "$superseded" ]; then echo "Superseded (OK — a newer migration redefined their function; not re-run):$superseded"; fi
if [ -n "$AFTER" ] && [ -z "$missing" ]; then
  say "DB READY — tell Claude 'db ho gaya' and it will push the app."
  echo "If the app was deployed BEFORE this DB step: no restart needed — the data gateway re-reads the schema by itself within 30 s (R-1671)."
else
  echo "Still missing:${missing:- (could not read live)} — send Claude this screen."; exit 1
fi
